def get_Inv_Count(arr, n):
    """Write a python function to count inversions in an array."""
    inv_count = 0
    n = min(n, len(arr))
    for i in range(n):
        for j in range(i + 1, n):
            if arr[i] > arr[j]:
                inv_count += 1
    return inv_count
